import { SendHog } from '@sendhog/sdk';

const client = new SendHog({ apiKey: process.env.SENDHOG_API_KEY ?? '' });

const result = await client.sendBulk({
  "from": "hello@example.com",
  "template": {
    "id": "welcome",
    "variables": {
      "product": "Example"
    }
  },
  "recipients": [
    {
      "to": "alex@example.net",
      "variables": {
        "name": "Alex"
      }
    },
    {
      "to": "sam@example.net",
      "variables": {
        "name": "Sam"
      }
    }
  ]
}, { idempotencyKey: 'welcome-batch-001' });

for (const recipient of result.results) {
  console.log(recipient.to, recipient.status, recipient.id);
}

