import { SendHog } from '@sendhog/sdk';

const client = new SendHog({ apiKey: process.env.SENDHOG_API_KEY ?? '' });

// Requires a key with webhooks.manage scope.
const { webhook, secret } = await client.webhooks.create({
  "url": "https://example.com/webhooks/sendhog",
  "events": [
    "email.delivered",
    "email.bounced",
    "email.complained"
  ]
});
// Store secret securely; it is shown only once. Do not log it.
console.log(webhook.id);

