import { SESv2Client, SendEmailCommand } from '@sendhog/sdk/ses';

const apiKey = process.env.SENDHOG_API_KEY;
if (!apiKey) throw new Error('Set SENDHOG_API_KEY on your server.');
const client = new SESv2Client({ apiKey });

const result = await client.send(new SendEmailCommand({
  "FromEmailAddress": "sender@example.com",
  "Destination": {
    "ToAddresses": [
      "recipient@example.net"
    ]
  },
  "Content": {
    "Simple": {
      "Subject": {
        "Data": "Hello from SendHog"
      },
      "Body": {
        "Text": {
          "Data": "Hello from your application."
        }
      }
    }
  }
}));
console.log(result.MessageId);

